114	    await page.goto('/clients');
115	    await page.getByTestId('client-open-1').click();
116	
117	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
118	    await expect(page.getByTestId('client-projects-table')).toBeVisible();
119	    await expect(page.getByTestId('client-projects-empty')).toHaveCount(0);
120	
121	    // The archived project is kept off the client's list; the live one remains.
122	    await expect(page.getByTestId('project-row-1')).toHaveCount(0);
123	    await expect(page.getByTestId('project-row-2')).toBeVisible();
124	    await expect(page.getByTestId('project-row-2').getByTestId('project-name')).toHaveText('Mobile app');
125	
126	    // The other client's project is not here either; only the one live project shows.
127	    await expect(page.getByTestId('project-row-3')).toHaveCount(0);
128	    await expect(page.getByTestId('project-name')).toHaveCount(1);
